const CACHE='one-line-static-v1';
const FILES=['./','./index.html','./styles/tokens.css','./styles/app.css','./src/main.js','./src/ui.js','./src/quotes.js','./src/storage.js','./src/drawing.js','./src/backup.js','./src/share.js','./data/quotes.original.json','./assets/icon.svg','./manifest.webmanifest'];
self.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(FILES))));
self.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('one-line-static-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));
self.addEventListener('message',event=>{if(event.data==='ACTIVATE')self.skipWaiting();});
self.addEventListener('fetch',event=>{if(event.request.method!=='GET'||new URL(event.request.url).origin!==self.location.origin)return;const url=new URL(event.request.url);const path=url.href.split('?')[0];const allowed=FILES.some(file=>new URL(file,self.registration.scope).href===path);if(!allowed&&!event.request.mode.includes('navigate'))return;event.respondWith(caches.open(CACHE).then(async cache=>{const cached=await cache.match(event.request,{ignoreSearch:true});if(cached)return cached;try{return await fetch(event.request);}catch(error){if(event.request.mode==='navigate')return cache.match('./index.html');throw error;}}));});
